// Template Declaration using type parameter T
template <typename T>
T find_maximum(T a, T b) {
    return (a > b) ? a : b;
}

// Type deduction/Implicit Instantiation (T is inferred as int)
int result_i = find_maximum(50, 100);

// Explicit Instantiation (T is explicitly set to float)
float result_f = find_maximum<float>(1.2f, 3.5f);

// Declaration using 'class' alias for type parameters
template <class Type>
Type absolute_value(Type val) {
    return (val < 0) ? -val : val;
}
